    cards=''.join(f'<article class="integration-card reveal" data-category="{cat.lower()}" data-search="{html.escape((name+" "+desc).lower(),quote=True)}"><div class="integration-head"><span class="integration-monogram" aria-hidden="true">{html.escape(mark)}</span><span class="pill">{cat}</span></div><h3>{name}</h3><p>{desc}</p><button type="button" class="text-link" data-integration="{key}" aria-haspopup="dialog">Connection details {icon("arrow")}<span class="sr-only"> for {name}</span></button></article>' for key,name,cat,mark,desc,detail,href in INTEGRATIONS)
