PAGES={
'index':('Your ideas. Within REACH.','Bring your models, code, and agents into one connected workspace. Discover SignalREACH, the open-source AI workspace ecosystem.',home),
'platform':('One ecosystem. Four ways to work.','Explore REACH Studio, the SimpleRAG relay and panel, the VS Code extension, and the desktop tray bridge.',platform),
'integrations':('Your tools, connected.','Explore SignalREACH endpoints, workspaces, and provider bridge options. Filter integrations and review connection requirements.',integrations),
'docs':('Documentation and quick start.','Start REACH Studio from source, configure your endpoint, and find the SignalREACH setup and security guides.',docs),
'about':('Built to bring things together.','Learn about SignalREACH, the independent open-source RAG Endpoint and AI Chat Host project.',about),
'download':('Get started with SignalREACH.','Choose your environment, view source setup commands, and find current SignalREACH releases and guides.',download)
}

def build():
    for name,(title,description,render) in PAGES.items():
        chat_scripts = '<script src="assets/chat-engine.js" defer></script><script src="assets/chat-ui.js" defer></script>' if name == 'index' else ''
        doc=f'''<!DOCTYPE html>
<html lang="en" data-theme="dark" data-motion="on">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{html.escape(description,quote=True)}"><meta name="theme-color" content="#161618"><meta name="color-scheme" content="dark light"><meta property="og:type" content="website"><meta property="og:title" content="SignalREACH — {html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><title>{html.escape(title)} | SignalREACH</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><script src="assets/theme.js"></script><link rel="stylesheet" href="assets/styles.css"><script src="assets/data.js" defer></script>{chat_scripts}<script src="assets/app.js" defer></script></head>
<body id="top" data-page="{name}" class="{"home-page" if name=="index" else "subpage"}">{header(name)}<main id="main">{render()}</main>{footer()}{dialogs()}<noscript><div class="notice"><p>The site content and links work without JavaScript. Enable JavaScript to use theme switching, interactive previews, search, and dynamic guide panels.</p></div></noscript></body></html>'''
        (ROOT/f'{name}.html').write_text(doc,encoding='utf-8')
    # Trusted local integration data; separate from user-entered search text.
    import json
    (ROOT/'assets'/'integration-data.json').write_text(json.dumps([dict(id=k,name=n,category=c,mark=m,description=d,detail=t,href=h) for k,n,c,m,d,t,h in INTEGRATIONS],ensure_ascii=False,indent=2),encoding='utf-8')
    (ROOT/'assets'/'data.js').write_text('window.REACH_DATA = '+json.dumps({'icons':ICONS,'integrations':[dict(id=k,name=n,category=c,mark=m,description=d,detail=t,href=h) for k,n,c,m,d,t,h in INTEGRATIONS],'curl':DEFAULT_CODE,'studioCommands':STUDIO_COMMANDS},ensure_ascii=False)+';\n',encoding='utf-8')
    print('Built '+', '.join(f'{name}.html' for name in PAGES))

if __name__=='__main__':
    build()
